const listHoldings = `-- name: ListHoldings :many
SELECT player_id, holding_id, level FROM app.player_holdings WHERE player_id = $1
`

func (q *Queries) ListHoldings(ctx context.Context, playerID uuid.UUID) ([]AppPlayerHolding, error) {
	rows, err := q.db.Query(ctx, listHoldings, playerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AppPlayerHolding{}
	for rows.Next() {
		var i AppPlayerHolding
		if err := rows.Scan(&i.PlayerID, &i.HoldingID, &i.Level); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

